"""Per-detector markdown reports rendered from harness results.

Reports are runtime output (``reports/<detector>.md``, ``reports/summary.md``)
and are git-ignored: every number in them comes from the run that produced
them, never from a hand-edited file.
"""

from __future__ import annotations

import time
from collections.abc import Sequence
from pathlib import Path
from typing import TYPE_CHECKING, Any

if TYPE_CHECKING:
    from zdp.harness.runner import ScenarioResult

_NOTICE = (
    "> Generated by `python -m zdp.harness` — do not edit. Values are computed at runtime "
    "from the fixtures listed below. Results on the bundled synthetic `fixtures` suite verify "
    "detector logic against known ground truth; they are **not** a performance benchmark. "
    "Benchmark figures (e.g. CTU-13) come only from a harness run over that dataset."
)


def _fmt(value: float, undefined: bool) -> str:
    return "n/a" if undefined else f"{value:.3f}"


def _ts(value: float) -> str:
    return time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(value))


def _metric_row(name: str, m: dict[str, Any]) -> str:
    und = set(m["undefined"])
    return (
        f"| {name} | {m['tp']} | {m['fp']} | {m['fn']} | {m['duplicates']} | "
        f"{_fmt(m['precision'], 'precision' in und)} | {_fmt(m['recall'], 'recall' in und)} | "
        f"{_fmt(m['f1'], 'f1' in und)} |"
    )


_TABLE_HEAD = [
    "| | TP | FP | FN | dup | precision | recall | F1 |",
    "|---|---:|---:|---:|---:|---:|---:|---:|",
]


def _header(metrics: dict[str, Any], title: str) -> list[str]:
    s = metrics["settings"]
    return [
        f"# {title}",
        "",
        _NOTICE,
        "",
        f"- Suite: `{metrics['suite']}`",
        f"- Framework version: `{metrics['framework_version']}`",
        f"- Config hash: `{metrics['config_hash']}`",
        f"- Generated: `{metrics['generated_at']}`",
        f"- Matching: ±{s['tolerance_seconds']:g} s tolerance, dedup policy `{s['dedup_policy']}`",
        "",
    ]


def render_detector_report(
    name: str, metrics: dict[str, Any], results: Sequence[ScenarioResult]
) -> str:
    lines = _header(metrics, f"Harness report: `{name}`")
    lines += ["## Pooled result", "", *_TABLE_HEAD, _metric_row(name, metrics["detectors"][name])]
    m = metrics["detectors"][name]
    if m["undefined"]:
        lines += [
            "",
            f"Undefined (zero denominator, reported as n/a): {', '.join(m['undefined'])}.",
        ]
    lines += ["", "## Per scenario", "", *_TABLE_HEAD]
    for res in results:
        lines.append(_metric_row(res.name, metrics["scenarios"][res.name]["detectors"][name]))

    tps = [(res.name, det, lbl) for res in results for det, lbl in res.matches[name].true_positives]
    fps = [(res.name, det) for res in results for det in res.matches[name].false_positives]
    fns = [(res.name, lbl) for res in results for lbl in res.matches[name].false_negatives]
    lines += ["", "## True positives", ""]
    lines += [
        f"- `{scen}` {det.src} → {det.dst or '-'} `{det.indicator}` "
        f"confidence {det.confidence:.2f} ({det.severity}, {det.technique_id}) at {_ts(det.ts)} — "
        f"label: {lbl.note or 'n/a'}"
        for scen, det, lbl in tps
    ] or ["_none_"]
    lines += ["", "## False negatives (missed labels)", ""]
    lines += [
        f"- `{scen}` {lbl.src} → {lbl.dst or '-'} window {_ts(lbl.window[0])}–{_ts(lbl.window[1])}"
        f" — {lbl.note}"
        for scen, lbl in fns
    ] or ["_none_"]
    lines += ["", "## False positives", ""]
    lines += [
        f"- `{scen}` {det.src} → {det.dst or '-'} `{det.indicator}` confidence "
        f"{det.confidence:.2f} at {_ts(det.ts)}; evidence keys: "
        f"{', '.join(sorted(det.evidence)[:8])}"
        for scen, det in fps
    ] or ["_none_"]
    return "\n".join(lines) + "\n"


def render_summary(metrics: dict[str, Any], results: Sequence[ScenarioResult]) -> str:
    lines = _header(metrics, "Harness summary")
    lines += ["## Per detector (pooled across scenarios)", "", *_TABLE_HEAD]
    lines += [_metric_row(n, m) for n, m in metrics["detectors"].items()]
    lines += [_metric_row("**overall (micro)**", metrics["overall"])]
    lines += [
        "",
        "## Scenarios",
        "",
        "| scenario | labels | detections | FP | FN | duplicates |",
        "|---|---:|---:|---:|---:|---:|",
    ]
    for res in results:
        s = metrics["scenarios"][res.name]
        lines.append(
            f"| {res.name}{' (pure negative)' if s['pure_negative'] else ''} | {s['n_labels']} | "
            f"{s['n_detections']} | {len(s['false_positives'])} | {len(s['false_negatives'])} | "
            f"{s['duplicates']} |"
        )
    return "\n".join(lines) + "\n"


def write_reports(
    metrics: dict[str, Any], results: Sequence[ScenarioResult], directory: Path
) -> list[Path]:
    directory.mkdir(parents=True, exist_ok=True)
    written = []
    for name in metrics["detectors"]:
        path = directory / f"{name}.md"
        path.write_text(render_detector_report(name, metrics, results), encoding="utf-8")
        written.append(path)
    summary = directory / "summary.md"
    summary.write_text(render_summary(metrics, results), encoding="utf-8")
    written.append(summary)
    return written
